"""Build the current review walkthrough from functionality and native evidence."""
from pathlib import Path
from datetime import datetime,timezone
import html,json,re,shutil,hashlib
from markdown_it import MarkdownIt
ROOT=Path(__file__).resolve().parents[2];D=ROOT/'docs';A=D/'v07-assets';A.mkdir(exist_ok=True)
board_dims=tuple(map(int,re.search(r'BOARD_SIZE_MM=\((\d+),(\d+)\)',(ROOT/'source/generator/rev07.py').read_text()).groups()))
def esc(s):return html.escape(str(s))
table=[]
for line in (D/'CURRENT_FUNCTIONALITY.md').read_text().splitlines():
 if line.startswith('|') and not line.startswith('|---'):
  table.append([s.strip() for s in line.strip('|').split('|')])
checks=[]
for cell,folder in [('Motor supply','motor-addon'),('USB power','usb-power'),('CAN / PWM I/O','robot-io'),('USB3 hub','usb3-front-end')]:
 f=ROOT/'outputs'/f'{folder}-design'/'validation.json'
 if f.exists():
  data=json.loads(f.read_text());status=data['status']
  stale=any(not (ROOT/name).exists() or hashlib.sha256((ROOT/name).read_bytes()).hexdigest()!=digest for name,digest in data.get('sha256',{}).items())
  if stale:status='STALE — RECHECK REQUIRED'
  detail=f"{data['footprints']} components; {data['drc_errors']} DRC errors; {data['drc_warnings']} warnings. Independent schematic and pad checks: {status}."
 else:status='IN PROGRESS';detail='Physical routing and independent checks are not complete.'
 checks.append(f'<tr><td>{esc(cell)}</td><td>{esc(status)}</td><td>{esc(detail)}</td></tr>')
rows=''.join('<tr>'+''.join(f'<{"th" if i==0 else "td"}>{esc(v)}</{"th" if i==0 else "td"}>' for v in row)+'</tr>' for i,row in enumerate(table))
for source,name in [(ROOT/'outputs/motor-addon-design/assembly-top.svg','motor-assembly.svg'),(ROOT/'outputs/usb-power-design/assembly-top.svg','usb-power-assembly.svg')]:
 if source.exists():shutil.copyfile(source,A/name)
stamp=datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC')
style='''body{max-width:1180px;margin:24px auto;padding:0 20px 60px;font:16px/1.5 system-ui,sans-serif;color:#202b30}h1{font-size:30px;line-height:1.2}h2{font-size:23px;border-top:1px solid #bdc6ca;padding-top:20px;margin-top:32px}a{color:#135a7b}nav{display:flex;gap:18px;flex-wrap:wrap;border-bottom:1px solid #bdc6ca;padding:12px 0}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid #d1d7da}th{background:#eef2f4}.notice{border:2px solid #926326;padding:12px 16px;background:#fffaf0}summary{cursor:pointer;padding:10px;background:#eef2f4}details{margin:12px 0}img{max-width:100%;height:auto}.diagram{display:grid;grid-template-columns:1fr 2fr;gap:8px;font-size:14px}.diagram div{border:1px solid #b8c2c7;padding:10px}.small{font-size:13px;color:#48575e}li{margin:8px 0}section{scroll-margin-top:20px}.scroll{overflow:auto}@media print{nav{display:none}tr{break-inside:avoid}h2{break-after:avoid}}'''
body=f'''<p class="small">Robot PDB v0.7 development · Evidence updated {stamp}</p>
<h1>Replacement wheels and USB3: review walkthrough</h1>
<div class="notice"><strong>Fabrication is still on hold.</strong> The saved factory draft contains the earlier v0.6 board. It does not include these additions. Passing cell checks below do not release the combined board. No payment has been made.</div>
<p><strong>Wrap-up recommendation:</strong> do not order this unfinished integrated revision. <a href="V07_WRAPUP.md">Read the risk, modularity, section-cost and disable-link report</a>. Fitted catalog components total about$168.60 per board at two-board quantities; assembly and hand-fit/external items are additional.</p><nav><a href="#review-V07_WRAPUP">Wrap-up report</a><a href="#functions">Connections</a><a href="#thor">Thor power</a><a href="#usb">USB arrangement</a><a href="#switch">Hardware switch</a><a href="#battery">Battery monitoring</a><a href="#checks">Checks</a><a href="#bench">Commissioning</a></nav>
<section id="functions"><h2>All user-facing connections</h2><p>The design replaces the Flipsky wheels with two DDSM350-CT wheels. It adds camera/microphone USB3 connections and three MG90S servo sockets. The combined layout target is <strong>{board_dims[0]} × {board_dims[1]} mm</strong>; the owner has confirmed there is no enclosure footprint limit. The extra routing space separates power and USB paths. The 0.8 mm board requires nylon/insulating M3 supports and independent heavy-wire strain relief. Mounting and connector access still need a final visual review.</p><div class="scroll"><table>{rows}</table></div></section>
<section id="thor"><h2>Thor power: one ready-made cable</h2><p>The confirmed 27–33V battery range feeds an onboard step-down supply at about 24.33V. Input parts still accommodate 33.6V full charge. J3 is a four-contact Micro-Fit header: two positive contacts and two grounds. A factory-crimped <strong>Molex 2147551042, 300mm, 18AWG</strong> cable connects the board directly to Thor, replacing the bare-wire adapter.</p><p>The official Molex drawing verifies that the cable swaps contacts within each polarity pair (1↔2 and 3↔4), preserving Thor’s two positives and two grounds. Check delivered-part fit and meter polarity before connecting Thor. Keep cable forces off the 0.8mm board with local insulating support and strain relief. <a href="THOR_POWER_CABLE.md">Connector, cable and supplier evidence</a>.</p></section>
<section id="usb"><h2>One USB cable to the Jetson</h2><div class="diagram"><div>Jetson USB3 → USB5744 hub</div><div>OAK-D USB-C: direct USB3 data, protected 5V power<br>USB-A microphone: USB3-capable port, also accepts USB2 devices<br>Internal USB2 child hub: audio, Dynamixel, wheel CAN, three-channel PWM<br>Fourth hub port: battery telemetry provision</div></div>
<p>The OAK-D path is USB3 end to end. It bypasses the USB2 child hub. Use a USB3 cable; a USB-C plug alone does not establish its data speed. Camera resolution/frame rate and simultaneous microphone operation still require hardware testing.</p>
<details><summary>How wheel and servo control use that cable</summary><p>One STM32 controller appears as a USB CAN adapter and connects through a CAN transceiver to the two addressed wheels. A second controller accepts USB commands for three independent PWM signals. Separate controllers preserve the standard CAN driver and keep its timing separate from servo firmware. Shutting down the CAN transceiver does not prove that a wheel stops; the wheel command-timeout behavior must be checked with the wheels raised.</p><p>The PWM firmware requires explicit arming, accepts 1000–2000µs commands at 50Hz, and disables signals on reset, disconnect, USB suspend or a 500ms command timeout. A hardware watchdog also resets a stalled controller. These are built and tested firmware behaviors; the physical board and actual servos still need commissioning. Servo 5V remains on until the master switch is OFF. The actual MG90S behavior when pulses disappear also needs a bench check.</p></details>
<p>The USB supply and small-servo supply are dedicated branches. Neither is added to the XL330 supply. The new USB supply is a 5.1V / 8A design target; that is not a measured thermal rating.</p></section>
<section id="switch"><h2>The master switch stays mechanical</h2><p>One external DPST switch uses four heavy wires: pack A positive in and out, and pack B positive in and out. Both positive paths open before they join the board. Battery negatives stay common. <strong>Stop the robot before switching OFF.</strong></p><p>The selected switch must be rated to interrupt the remaining computer/electronics DC load. Stopping the wheels does not make a no-load isolator suitable. <a href="MASTER_DISCONNECT_SELECTION.md">Switch selection evidence and remaining procurement check</a>.</p><p>There is no software permission or shutdown supervisor controlling the battery switch. Small hardware supervisors in the USB circuit only start its voltage rails and reset correctly.</p><p>The dedicated motor converter regulates about 22.34V. Separate input reverse-polarity protection feeds the motor buck, and an output reverse blocker keeps returned motor energy out of it. A separate motor-side comparator and switch send braking energy into an external 3.3Ω chassis resistor, including after the battery switch opens. A normally closed one-shot thermal cutoff disables the motor buck if the resistor overheats. The provisional choices are Vishay NH1003R300FE01 and SCHOTT SEFUSE SM110A0; supplier availability and actual mounted thermal behaviour still need confirmation. The thermal-contact input now includes filtering and a negative-voltage clamp.</p></section>
<section id="battery"><h2>Two Daly batteries over USB</h2><p>The owner's purchase description is Daly TH Smart Active Balance, 4–8S, 60A. The supplier-linked manual covers an 8S/60A TH model and lists serial and optional CAN/RS485 communications.</p><p>The reserved fourth USB hub port can serve one additional dual-serial bridge, with a separate isolation barrier for each pack. Targets are pack voltage, signed current, charge percentage, eight cell voltages, temperatures and faults. A stale/disconnected battery must appear unknown. The two parallel pack voltages must never be added.</p><p>The exact battery cable is pending verification. The accessory connector also carries power; its RX/TX descriptions and connector orientation are insufficient to wire safely from the listing. There are no captured live BMS readings in the repo yet. <a href="DALY_USB_REVIEW.md">Evidence and remaining details</a>.</p></section>
<section id="checks"><h2>What has actually been checked</h2><table><tr><th>Cell</th><th>Status</th><th>Evidence</th></tr>{''.join(checks)}</table>
<p>The converter calculations screen component tolerances, current-limit assumptions and an averaged feedback-loop model. They do not measure real loop stability, heat, braking overshoot or USB signal quality. Custom passive schematic symbols also limit the coverage of electrical-rule checking.</p>
<details><summary>Motor supply component layout</summary><img src="v07-assets/motor-assembly.svg" alt="Actual motor supply development cell component drawing"></details>
<details><summary>Dedicated USB supply component layout</summary><img src="v07-assets/usb-power-assembly.svg" alt="Actual USB supply development cell component drawing"></details>
<p><strong>Before fabrication:</strong> complete combined-board routing and pin/net comparison; zero native DRC errors and opens; inspect exact footprints and factory placements; agree the manufacturer stackup and USB impedance; finish branch fuse/harness and resistor thermal details. Confirm the DDSM350's permitted voltage and transient limits rather than treating its nominal 24V label as a full operating specification. <a href="GEMINI_v07_RECONCILIATION.md">Gemini findings and verified dispositions</a>.</p><p>Additional manufacturer checks: <a href="USB_POWER_CAPACITORS.md">camera capacitor selection and effective capacitance</a>; <a href="USB2_CHILD_LINK_REVIEW.md">internal High-Speed USB length and matching</a>; <a href="USB_HUB_CONFIGURATION.md">USB hub configuration and programming</a>. Local bypass capacitors are being placed beside their own chips before final data routing. These reviews do not release an unfinished layout.</p><p>The signed-in factory form offers the340 ×260mm,0.8mm stackup with the required fine vias. Its preliminary price is<strong>$325.04 for five bare PCBs</strong>, excluding assembly/components/shipping and before Gerber upload. <a href="V07_FACTORY_PREFLIGHT.md">Factory settings, the size-limit discrepancy and preliminary quote evidence</a>.</p><p><strong>Cost:</strong> the saved live JLC catalog snapshot prices dedicated CAN components at $7.263 per board for two boards. Shared hub/power, board area, assembly fees, attrition, shipping, tax and programming are excluded. The final assembled-order increase remains pending; this component snapshot is not a firm assembly quote.</p></section>
<section id="bench"><h2>First power-up and bench testing</h2><ol><li>Inspect polarity, isolation, fuses, switch mapping and soldering with power absent. Check harness strain relief and all connector labels.</li><li>Start each power branch on a current-limited supply with dummy loads. Verify voltage, startup, ripple, load steps, current-limit behavior and temperatures before connecting expensive equipment.</li><li>Test the motor dump with bounded energy and an independent safe sink. Measure thresholds, overshoot, resistor temperature and switch-off behavior. About 8.2J is the translational energy of a 20lb robot at 3mph; wheels, slopes and repeated braking add energy.</li><li>Flash and verify both controller images. Test CAN addressing and termination, PWM arming, timeout, unplug, suspend, reset and watchdog behavior with wheels lifted and small servo loads first.</li><li>Use an independent controlled bench sink for servo backdrive/deceleration tests. Restrict motion and torque until rail peaks stay below actuator limits; bulk capacitors are not a braking sink. Full robot operation needs a validated energy limit or clamp arrangement.</li><li>Test OAK-D requested resolution/frame rate while streaming microphone audio and using every internal USB device. Test both USB-C plug orientations, suspend/resume and brownout recovery.</li><li>Verify the Daly interface with the matched vendor cable and protocol first, then read-only logging. Test each link sleeping, disappearing or restarting independently.</li><li>Only then increase load within measured limits. Confirm pack sharing and behavior when one BMS opens. A 60A BMS label does not upgrade the cells' published pack current rating.</li></ol>
<p>The old <a href="PROTOTYPE_v0.6_WALKTHROUGH.html">v0.6 wiring/review walkthrough</a> and <a href="ROBOT_PDB_LEARNING_REPORT.html">illustrated learning report</a> remain available for history. The old wheel version is preserved on <a href="#">the remote archive branch</a>.</p></section>'''
#Keep the requested evidence readable inside the walkthrough itself. The
#browser does not provide a usable page for raw Markdown document links.
reviews=['THOR_POWER_CABLE','GEMINI_v07_RECONCILIATION','DALY_USB_REVIEW',
         'USB_POWER_CAPACITORS','USB2_CHILD_LINK_REVIEW','USB_HUB_CONFIGURATION',
         'USB_CONNECTOR_MECHANICAL_REVIEW','MASTER_DISCONNECT_SELECTION',
         'BATTERY_TELEMETRY','USB_BYPASS_REVIEW','V07_FACTORY_PREFLIGHT','V07_WRAPUP','USB_CHECKPOINT_HANDOFF']
renderer=MarkdownIt('commonmark',{'html':False}).enable('table')
body+='<section id="reviews"><h2>Detailed review evidence</h2>'
for name in reviews:
 source=ROOT/'revisions/usb3-front-end/diagnostics/wrapup-2026-11-09/README.md' if name=='USB_CHECKPOINT_HANDOFF' else D/(name+'.md')
 text=source.read_text();title=text.splitlines()[0].lstrip('# ')
 body+=f'<details id="review-{name}"><summary>{esc(title)}</summary>'+renderer.render(text)+'</details>'
body+='</section>'
for name in reviews:body=body.replace('href="'+name+'.md"','href="#review-'+name+'"')
body=body.replace('href="../revisions/usb3-front-end/diagnostics/wrapup-2026-11-09/README.md"','href="#review-USB_CHECKPOINT_HANDOFF"')
body+="""<script>function openReview(){const e=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(e&&e.tagName==="DETAILS")e.open=true;}addEventListener("hashchange",openReview);document.addEventListener("click",e=>{const a=e.target.closest('a[href^="#review-"]');if(a){const d=document.getElementById(a.hash.slice(1));if(d)d.open=true;}});openReview();</script>"""
(D/'PROTOTYPE_v0.7_WALKTHROUGH.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robot PDB v0.7 review walkthrough</title><style>'+style+'</style><main>'+body+'</main></html>')
print('Built current v0.7 walkthrough')
